package com.bank.immutability;

import java.math.BigDecimal;
import java.util.logging.*;

public class FinalKeywordDemo {
    // final static field = class-level constant, assigned once
    static final String BANK_NAME = "National Bank of India";

    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info(() -> "Bank: " + BANK_NAME);

        SavingsAccount rajesh = new SavingsAccount("SAV2001", "Rajesh Kumar",
                                                   new Money(new BigDecimal("1000000.00")));
        log.info(() -> "Account " + rajesh.getAccountId()
                        + " monthly fee = " + rajesh.calculateMonthlyFee());

        rajesh.transfer(new Money(new BigDecimal("50000")));
    }
}

