// final CLASS: cannot be extended, guaranteeing its invariants hold.
final class Money {
    private final BigDecimal amount; // final FIELD: assigned once in constructor
    Money(BigDecimal amount) { this.amount = amount; }
    BigDecimal getAmount() { return amount; }
    Money minus(Money other) { return new Money(amount.subtract(other.amount)); }
    public String toString() { return "Rs." + amount; }
}

// ─── Would be Account.java in a real project ───
class Account {
    private final String accountId;   // final FIELD: never changes after open
    private final String holderName;
    private Money balance;
    Account(String accountId, String holderName, Money balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
    }
    String getAccountId() { return accountId; }
    Money getBalance() { return balance; }

    // final METHOD: subclasses inherit but cannot override this regulated rule.
    final Money calculateMonthlyFee() {
        return new Money(new BigDecimal("100.00"));
    }

    // final PARAMETER: 'amount' cannot be reassigned inside the method body.
    void transfer(final Money amount) {
        // amount = new Money(BigDecimal.ZERO); // <- would be a COMPILE ERROR
        Logger log = Logger.getLogger("BankLog");
        balance = balance.minus(amount);
        log.info(() -> accountId + " transferred " + amount
                        + ", new balance " + balance);
    }
}

// ─── Would be SavingsAccount.java in a real project ───
class SavingsAccount extends Account {
    SavingsAccount(String id, String name, Money bal) { super(id, name, bal); }
    // Cannot override calculateMonthlyFee() because it is final in Account.
}
